 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks `ko` or `en` from an Accept-Language header (q-values, region tags); `fallback` if neither is listed. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  const ranked = header
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...attrs] = part.trim().split(";");
+      const q = attrs.map((a) => a.trim().match(/^q=(\d*\.?\d+)$/i)).find(Boolean);
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: q ? Number(q[1]) : 1, index };
+    })
+    .filter((x) => (x.lang === "ko" || x.lang === "en") && x.q > 0)
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  return ranked.length ? ranked[0].lang : fallback;
+}
